// SmartGarbage: Dark mode, accessibility toolbar, and language switch
document.addEventListener("DOMContentLoaded", function() {
  // Dark mode toggle
  var darkToggle = document.getElementById("darkModeToggle");
  var darkIcon = document.getElementById("darkModeIcon");
  var savedTheme = localStorage.getItem("theme");
  if (savedTheme === "dark") {
    document.documentElement.setAttribute("data-theme", "dark");
    if (darkIcon) darkIcon.textContent = "\u2600\uFE0F";
  } else if (savedTheme === "light") {
    document.documentElement.removeAttribute("data-theme");
    if (darkIcon) darkIcon.textContent = "\uD83C\uDF19";
  } else if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) {
    document.documentElement.setAttribute("data-theme", "dark");
    if (darkIcon) darkIcon.textContent = "\u2600\uFE0F";
  }
  if (darkToggle) {
    darkToggle.addEventListener("click", function() {
      var isDark = document.documentElement.getAttribute("data-theme") === "dark";
      if (isDark) {
        document.documentElement.removeAttribute("data-theme");
        localStorage.setItem("theme", "light");
        if (darkIcon) darkIcon.textContent = "\uD83C\uDF19";
      } else {
        document.documentElement.setAttribute("data-theme", "dark");
        localStorage.setItem("theme", "dark");
        if (darkIcon) darkIcon.textContent = "\u2600\uFE0F";
      }
    });
  }
  // Accessibility toolbar: text-resize + high-contrast (WCAG AA)
  var TEXT_STEPS = [100, 112.5, 125];
  var applyTextSize = function(step) {
    document.documentElement.style.fontSize = step + "%";
    localStorage.setItem("sgTextSize", String(step));
  };
  var textSize = parseInt(localStorage.getItem("sgTextSize") || "100", 10);
  applyTextSize(textSize);
  var smallerBtn = document.getElementById("textSmallerBtn");
  var biggerBtn = document.getElementById("textBiggerBtn");
  var resetBtn = document.getElementById("textResetBtn");
  var contrastBtn = document.getElementById("contrastToggleBtn");
  if (smallerBtn) smallerBtn.addEventListener("click", function() {
    textSize = TEXT_STEPS[Math.max(0, TEXT_STEPS.indexOf(textSize) - 1)];
    applyTextSize(textSize);
  });
  if (biggerBtn) biggerBtn.addEventListener("click", function() {
    textSize = TEXT_STEPS[Math.min(TEXT_STEPS.length - 1, TEXT_STEPS.indexOf(textSize) + 1)];
    applyTextSize(textSize);
  });
  if (resetBtn) resetBtn.addEventListener("click", function() { textSize = 100; applyTextSize(100); });
  var applyContrast = function(on) {
    document.documentElement.setAttribute("data-contrast", on ? "true" : "false");
    localStorage.setItem("sgHighContrast", on ? "1" : "0");
    if (contrastBtn) contrastBtn.setAttribute("aria-pressed", on ? "true" : "false");
  };
  if (contrastBtn) {
    var savedContrast = localStorage.getItem("sgHighContrast") === "1";
    applyContrast(savedContrast);
    contrastBtn.addEventListener("click", function() {
      applyContrast(document.documentElement.getAttribute("data-contrast") !== "true");
    });
  }
  // Navbar toggler
  var toggler = document.querySelector(".navbar-toggler");
  var menu = document.getElementById("mainNavbarLayout");
  if (toggler && menu) {
    toggler.addEventListener("click", function() {
      var open = menu.classList.contains("show");
      if (open) {
        var inst = bootstrap.Collapse.getInstance(menu);
        if (inst) inst.hide(); else menu.classList.remove("show");
      } else {
        var inst2 = bootstrap.Collapse.getInstance(menu);
        (inst2 || new bootstrap.Collapse(menu)).show();
      }
    });
  }
});
// Language switch without redirect hop
document.querySelectorAll("a[data-lang]").forEach(function(link) {
  link.addEventListener("click", function(e) {
    e.preventDefault();
    var langUrl = link.getAttribute("data-lang-href");
    var dest = link.getAttribute("href");
    fetch(langUrl, { credentials: "same-origin" })
      .then(function() { location.href = dest; })
      .catch(function() { location.href = langUrl; });
  });
});
